/// <reference lib="webworker" />
import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { NetworkFirst, CacheFirst } from 'workbox-strategies';

declare const self: ServiceWorkerGlobalScope & {
  __WB_MANIFEST: Array<{ url: string; revision: string | null }>;
};

// Clean up old caches from previous versions
cleanupOutdatedCaches();

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Cache images and static assets with CacheFirst
registerRoute(
  ({ request }) => request.destination === 'image' || request.destination === 'font',
  new CacheFirst({
    cacheName: 'weatherboard-static-assets',
  })
);

// Cache weather API calls with NetworkFirst so offline returns latest cached weather
registerRoute(
  ({ url }) =>
    url.hostname.includes('openweathermap.org') ||
    url.hostname.includes('open-meteo.com') ||
    url.hostname.includes('rapidapi.com'),
  new NetworkFirst({
    cacheName: 'weatherboard-api-cache',
    networkTimeoutSeconds: 4,
  })
);

// Fallback runtime caching for document navigation
registerRoute(
  ({ request }) => request.mode === 'navigate',
  new NetworkFirst({
    cacheName: 'weatherboard-pages',
    networkTimeoutSeconds: 3,
  })
);

// Service worker activation & immediate take-over
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

// Periodic Sync or Background Notification Trigger
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) {
          return client.focus();
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow('/');
      }
    })
  );
});

// Handle push notifications if subscribed
self.addEventListener('push', (event) => {
  let title = 'WeatherBoard Update';
  let body = 'Check your daily meteorological conditions.';

  if (event.data) {
    try {
      const data = event.data.json();
      title = data.title || title;
      body = data.body || body;
    } catch {
      body = event.data.text();
    }
  }

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon: '/pwa-192x192.png',
      badge: '/favicon.svg',
      tag: 'weatherboard-daily-alert',
    })
  );
});

// Receive messages from clients (e.g. test notification trigger or time schedule)
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'TRIGGER_TEST_NOTIFICATION') {
    const { title, body } = event.data;
    self.registration.showNotification(title || 'WeatherBoard Forecast', {
      body: body || 'Weather update ready for your saved cities.',
      icon: '/pwa-192x192.png',
      badge: '/favicon.svg',
      tag: 'weatherboard-daily-reminder',
    });
  }
});
